function Invoke-AgentPython {
    param([Parameter(Mandatory = $true)][string[]]$Arguments)
    $agentPy = Join-Path $env:USERPROFILE '.ai-workspace\venv\Scripts\python.exe'
    $exe = if (Test-Path -LiteralPath $agentPy) { $agentPy } else { 'python' }
    # Capture stdout/stderr so they are NOT returned as the function output (would break exit-code checks).
    $output = & $exe @Arguments 2>&1
    $code = $LASTEXITCODE
    foreach ($line in $output) {
        Write-Info ([string]$line) DarkGray
    }
    return [int]$code
}

